(7560236, 1212094, 140305, '<td valign="top">Gorgeous shot</td>', 'Gorgeous shot', '2018-02-21 01:44:09.000000', NULL, 1),
(7560294, 1212050, 124815, '<td valign="top">the joy and misery of rain in one push of the button</td>', 'the joy and misery of rain in one push of the button', '2018-02-21 13:30:21.000000', NULL, 1),
(7560301, 1212093, 56502, '<td valign="top">I personally have a hard time taking interesting fotos of woods, so I''m very impressed when someone manages to do it as well as in this one!</td>', 'I personally have a hard time taking interesting fotos of woods, so I''m very impressed when someone manages to do it as well as in this one!', '2018-02-21 15:11:00.000000', NULL, 1),
(7560302, 1212050, 56502, '<td valign="top">I like the expression of the fun they seem to be having!</td>', 'I like the expression of the fun they seem to be having!', '2018-02-21 15:17:16.000000', NULL, 1),
(7560303, 1211822, 56502, '<td valign="top">Great use of leading lines!</td>', 'Great use of leading lines!', '2018-02-21 15:18:26.000000', NULL, 1),
(7560305, 1211695, 70661, '<td valign="top">This is the kind of stuff I love to find when I''m out for a drive! She''s a beauty! That patina!!!! One of my favs!</td>', 'This is the kind of stuff I love to find when I''m out for a drive! She''s a beauty! That patina!!!! One of my favs!', '2018-02-21 15:51:47.000000', NULL, 1),
